import numpy as np

def step_response(zeta, w, t):
    """y(t) for y'' + 2 zeta w y' + w^2 y = w^2, from y(0) = y'(0) = 0."""
    t = np.asarray(t, dtype=float)
    if abs(zeta - 1) < 1e-12:
        return 1 - (1 + w * t) * np.exp(-w * t)
    if zeta < 1:
        wd = w * np.sqrt(1 - zeta ** 2)
        return 1 - np.exp(-zeta * w * t) * (np.cos(wd * t) + zeta / np.sqrt(1 - zeta ** 2) * np.sin(wd * t))
    s = np.sqrt(zeta ** 2 - 1)
    r1, r2 = -w * (zeta - s), -w * (zeta + s)
    return 1 + (r2 * np.exp(r1 * t) - r1 * np.exp(r2 * t)) / (r1 - r2)
